css:
.bdl-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e0e6f0;
}
.bdl-sim-header {
    border-left: 4px solid #00ff88;
    padding: 20px 28px;
    margin-bottom: 24px;
    background: rgba(0,255,136,0.05);
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 16px;
}
.bdl-sim-header h1 {
    color: #00ff88;
    font-size: 1.3rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin: 0 0 6px 0;
    font-weight: 700;
}
.bdl-sim-subtitle {
    color: #6b7280;
    font-size: 0.8rem;
    letter-spacing: 0.04em;
}
.bdl-sim-period-counter {
    color: #00bfff;
    font-size: 0.9rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    font-weight: 600;
    padding: 8px 14px;
    border: 1px solid #1f2d3d;
    border-radius: 4px;
    background: #0a0f1e;
}
.bdl-sim-period-counter span {
    margin: 0 3px;
}
.bdl-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.bdl-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 18px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.2s ease;
}
.bdl-sim-kpi-card:hover {
    border-color: #2d3f55;
    transform: translateY(-2px);
}
.bdl-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00ff88, #00bfff);
}
.bdl-sim-kpi-label {
    color: #6b7280;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 10px;
    font-weight: 600;
}
.bdl-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #00ff88;
    letter-spacing: 0.01em;
    margin-bottom: 4px;
}
.bdl-sim-kpi-sub {
    color: #6b7280;
    font-size: 0.7rem;
    letter-spacing: 0.03em;
}
.bdl-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 4px solid #00bfff;
    border-radius: 8px;
    padding: 22px 28px;
    margin-bottom: 24px;
}
.bdl-sim-briefing h3 {
    color: #00bfff;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin: 0 0 12px 0;
    font-weight: 700;
}
.bdl-sim-round-title {
    font-size: 1.1rem;
    color: #e0e6f0;
    font-weight: 600;
    margin-bottom: 10px;
}
.bdl-sim-briefing-text {
    color: #9ca3af;
    line-height: 1.65;
    font-size: 0.95rem;
    margin: 0;
}
.bdl-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.bdl-sim-controls h3 {
    color: #ff6b35;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin: 0 0 20px 0;
    font-weight: 700;
}
.bdl-sim-decision-group {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px 20px;
}
.bdl-sim-field {
    display: flex;
    flex-direction: column;
}
.bdl-sim-field-wide {
    grid-column: 1 / -1;
}
.bdl-sim-controls label {
    color: #9ca3af;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    margin-bottom: 8px;
    display: block;
    font-weight: 600;
}
.bdl-sim-controls input[type="number"],
.bdl-sim-controls select {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.bdl-sim-controls input[type="number"]:focus,
.bdl-sim-controls select:focus {
    outline: none;
    border-color: #00ff88;
    box-shadow: 0 0 0 2px rgba(0,255,136,0.2);
}
.bdl-sim-controls select option {
    background: #111827;
    color: #e0e6f0;
}
.bdl-sim-button-row {
    display: flex;
    gap: 12px;
    margin-top: 24px;
    padding-top: 20px;
    border-top: 1px solid #1f2d3d;
    flex-wrap: wrap;
}
.bdl-sim-container .btn-primary {
    background: #00ff88;
    border: none;
    color: #0a0f1e;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    padding: 11px 26px;
    font-size: 0.82rem;
    border-radius: 4px;
    transition: background 0.2s ease, box-shadow 0.2s ease;
}
.bdl-sim-container .btn-primary:hover {
    background: #00d46f;
    box-shadow: 0 0 18px rgba(0,255,136,0.45);
}
.bdl-sim-container .btn-outline-secondary {
    background: transparent;
    border: 1px solid #2d3f55;
    color: #9ca3af;
    padding: 9px 18px;
    font-size: 0.78rem;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    font-weight: 600;
}
.bdl-sim-container .btn-outline-secondary:hover {
    background: #1f2d3d;
    color: #e0e6f0;
    border-color: #3d5775;
}
.bdl-sim-results {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 4px solid #ff6b35;
    border-radius: 8px;
    padding: 22px 28px;
    margin-bottom: 24px;
    min-height: 80px;
}
.bdl-sim-results h3 {
    color: #ff6b35;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin: 0 0 12px 0;
    font-weight: 700;
}
.bdl-sim-notes {
    color: #e0e6f0;
    line-height: 1.7;
    font-size: 0.93rem;
}
.bdl-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 16px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.bdl-sim-history table {
    color: #e0e6f0;
    background: transparent;
    margin: 0;
    width: 100%;
    border: none;
}
.bdl-sim-history table thead th {
    color: #00bfff;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    border-bottom: 1px solid #2d3f55;
    border-top: none;
    padding: 12px 14px;
    background: transparent;
    font-weight: 700;
}
.bdl-sim-history table tbody td {
    padding: 11px 14px;
    border-top: 1px solid #1f2d3d;
    color: #e0e6f0;
    font-size: 0.88rem;
    background: transparent;
}
.bdl-sim-history table tbody tr:hover td {
    background: #0a0f1e;
}
.bdl-sim-chart {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    height: 380px;
    position: relative;
}
@media (max-width: 768px) {
    .bdl-sim-container { padding: 16px; }
    .bdl-sim-header {
        flex-direction: column;
        align-items: flex-start;
    }
    .bdl-sim-header h1 { font-size: 1.05rem; }
    .bdl-sim-kpi-grid {
        grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
        gap: 12px;
    }
    .bdl-sim-kpi-value { font-size: 1.4rem; }
    .bdl-sim-decision-group { grid-template-columns: 1fr; }
    .bdl-sim-controls, .bdl-sim-briefing, .bdl-sim-results { padding: 18px; }
    .bdl-sim-chart { height: 300px; }
}

