                if (isNaN(decisions.rtoMinutes) || decisions.rtoMinutes < 1 || decisions.rtoMinutes > 1440) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('rto_warning'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var period = state.currentPeriod;
            var ds = state.domainState;
            var t = window.mySimulation.t.bind(window.mySimulation);

            var tpsDelta = 0;
            var costDelta = 0;
            var archDelta = 0;
            var complianceDelta = 0;
            var regulatorDelta = 0;
            var notes = '';

            if (period === 1) {
                if (d.bottleneckAnalysis === 'db_write_contention') {
                    archDelta += 15;
                    notes = t('note_r1_diag_correct');
                } else {
                    archDelta += 3;
                    notes = t('note_r1_diag_partial');
                }
                if (d.scalingApproach === 'horizontal') {
                    archDelta += 10;
                    notes += '<br>' + t('note_r1_horizontal');
                } else if (d.scalingApproach === 'hybrid') {
                    archDelta += 5;
                    notes += '<br>' + t('note_r1_hybrid');
                } else {
                    archDelta -= 5;
                    notes += '<br>' + t('note_r1_vertical');
                }
                var gapIdeal = 1205;
                // a blank or non numeric gap never earns the accuracy bonus
                var gapGiven = typeof d.targetTpsGap === 'number' && isFinite(d.targetTpsGap);
                var gapError = Math.abs(d.targetTpsGap - gapIdeal);
                if (gapGiven && gapError < 150) { archDelta += 5; }
                tpsDelta += 30;
                regulatorDelta += 5;
            } else if (period === 2) {
                if (d.writeDb === 'event_sourcing_kafka') {
                    tpsDelta += 1200; costDelta += 14; archDelta += 18; complianceDelta += 10;
                    notes = t('note_r2_eventsourcing');
                } else if (d.writeDb === 'cockroachdb') {
                    tpsDelta += 900; costDelta += 12; archDelta += 16; complianceDelta += 10;
                    notes = t('note_r2_cockroach');
                } else if (d.writeDb === 'sharded_postgres') {
                    tpsDelta += 500; costDelta += 8; archDelta += 10; complianceDelta += 4;
                    notes = t('note_r2_sharded');
                } else if (d.writeDb === 'cassandra') {
                    tpsDelta += 1500; costDelta += 10; archDelta += 5; complianceDelta -= 25; regulatorDelta -= 15;
                    notes = t('note_r2_cassandra');
                } else {
                    tpsDelta += 30; archDelta -= 5;
                    notes = t('note_r2_keep');
                }
                if (d.eventBus === 'kafka') {
                    archDelta += 10; costDelta += 4; complianceDelta += 5;
                    notes += '<br>' + t('note_r2_kafka');
                } else if (d.eventBus === 'kinesis') {
                    archDelta += 8; costDelta += 5; complianceDelta += 3;
                    notes += '<br>' + t('note_r2_kinesis');
                } else {
                    archDelta -= 5;
                    notes += '<br>' + t('note_r2_nobus');
                }
                if (d.analyticsWarehouse === 'snowflake' || d.analyticsWarehouse === 'bigquery' || d.analyticsWarehouse === 'redshift') {
                    archDelta += 8; costDelta += 8;
                    notes += '<br>' + t('note_r2_warehouse');
                } else {
                    archDelta -= 3;
                    notes += '<br>' + t('note_r2_nowarehouse');
                }
                regulatorDelta += 10;
            } else if (period === 3) {
                if (d.dataCatalog === 'glue') {
                    archDelta += 8; complianceDelta += 8; costDelta += 2;
                    notes = t('note_r3_glue');
                } else if (d.dataCatalog === 'hive') {
                    archDelta += 6; complianceDelta += 5; costDelta += 1;
                    notes = t('note_r3_hive');
                } else {
                    complianceDelta -= 10;
                    notes = t('note_r3_nocatalog');
                }
                if (d.partitioningStrategy === 'composite') {
                    archDelta += 12;
                    notes += '<br>' + t('note_r3_composite');
                } else if (d.partitioningStrategy === 'hash_userid') {
                    archDelta += 8;
                    notes += '<br>' + t('note_r3_hash');
                } else if (d.partitioningStrategy === 'date_department') {
                    archDelta += 2;
                    notes += '<br>' + t('note_r3_datedept');
                } else if (d.partitioningStrategy === 'random') {
                    archDelta -= 3;
                    notes += '<br>' + t('note_r3_random');
                } else {
                    archDelta -= 5;
                    notes += '<br>' + t('note_r3_keep');
                }
                if (d.sarlaftPipeline === 'kafka_consumer') {
                    complianceDelta += 15; archDelta += 8; regulatorDelta += 10;
                    notes += '<br>' + t('note_r3_sarlaft_kafka');
                } else if (d.sarlaftPipeline === 'hybrid') {
                    complianceDelta += 8; archDelta += 4; regulatorDelta += 5;
                    notes += '<br>' + t('note_r3_sarlaft_hybrid');
                } else if (d.sarlaftPipeline === 'batch_etl_optimized') {
                    complianceDelta += 3; regulatorDelta += 2;
                    notes += '<br>' + t('note_r3_sarlaft_batch');
                } else {
                    complianceDelta -= 10; regulatorDelta -= 5;
                    notes += '<br>' + t('note_r3_sarlaft_keep');
                }
                costDelta -= 5;
                tpsDelta += 60;
            } else if (period === 4) {
                // a blank or non numeric RTO never counts as a fast commitment
                var rtoGiven = typeof d.rtoMinutes === 'number' && isFinite(d.rtoMinutes);
                if (rtoGiven && d.rtoMinutes <= 5) {
                    regulatorDelta += 20; archDelta += 5;
                    notes = t('note_r4_rto_fast');
                } else if (rtoGiven && d.rtoMinutes <= 60) {
                    regulatorDelta += 10;
                    notes = t('note_r4_rto_med');
                } else {
                    regulatorDelta -= 10;
                    notes = t('note_r4_rto_slow');
                }
                if (d.rpoStrategy === 'zero_loss_kafka') {
                    regulatorDelta += 15; complianceDelta += 10;
                    notes += '<br>' + t('note_r4_rpo_zero');
                } else if (d.rpoStrategy === '5min_replication') {
                    regulatorDelta += 5;
                    notes += '<br>' + t('note_r4_rpo_5min');
                } else {
                    regulatorDelta -= 10;
                    notes += '<br>' + t('note_r4_rpo_1hour');
                }
                if (d.piiGovernance === 'encrypted_iam') {
                    complianceDelta += 20; regulatorDelta += 10;
                    notes += '<br>' + t('note_r4_pii_full');
                } else if (d.piiGovernance === 'partial') {
                    complianceDelta += 8;
                    notes += '<br>' + t('note_r4_pii_partial');
                } else {
                    complianceDelta -= 15; regulatorDelta -= 10;
                    notes += '<br>' + t('note_r4_pii_none');
                }
                tpsDelta += 20;
            }

            ds.tpsCapacity = Math.max(0, ds.tpsCapacity + tpsDelta);
            ds.monthlyCost = Math.max(0, ds.monthlyCost + costDelta);
            ds.architectureScore = Math.max(0, Math.min(100, ds.architectureScore + archDelta));
            ds.complianceScore = Math.max(0, Math.min(100, ds.complianceScore + complianceDelta));
            ds.regulatorConfidence = Math.max(0, Math.min(100, ds.regulatorConfidence + regulatorDelta));

            ds.archScoreHistory.push(ds.architectureScore);
            ds.complianceHistory.push(ds.complianceScore);
            ds.regulatorHistory.push(ds.regulatorConfidence);
            ds.tpsHistory.push(ds.tpsCapacity);
            ds.costHistory.push(ds.monthlyCost);

            // Platform score 0 to 100: the getPerformanceSummary overall, mean of architecture, compliance and regulator confidence, on the current values
            var runningOverall = Math.round(((ds.architectureScore || 0) + (ds.complianceScore || 0) + (ds.regulatorConfidence || 0)) / 3);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, runningOverall)) });

            var results = {
                period: state.currentPeriod,
                tpsCapacity: ds.tpsCapacity,
                monthlyCost: ds.monthlyCost,
                architectureScore: ds.architectureScore,
                complianceScore: ds.complianceScore,
                regulatorConfidence: ds.regulatorConfidence,
                notes: notes,
                tpsDelta: tpsDelta,
                costDelta: costDelta,
                archDelta: archDelta,
                complianceDelta: complianceDelta,
                regulatorDelta: regulatorDelta
            };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
                var notesEl = document.getElementById('resultNotes');
                if (notesEl) notesEl.innerHTML = notes;
            })(state.currentPeriod + 1), 400);

            return results;
        }

