        formatCompletionMessage(summary) {
            summary = summary || {};
            var lang = 'en';
            try { lang = ((window.mySimulation && window.mySimulation.config && window.mySimulation.config.language) || (document.documentElement && document.documentElement.getAttribute('lang')) || 'en').toLowerCase(); } catch (e) {}
            var es = lang.indexOf('es') === 0;
            var L = es ? { title:'\u00a1Simulaci\u00f3n completada!', perf:'Desempe\u00f1o', tps:'Capacidad TPS', comp:'Cumplimiento', reg:'Confianza del regulador', cost:'Coste mensual (COP, millones)', takeaways:'Conclusiones clave' } : { title:'Simulation complete!', perf:'Performance', tps:'TPS capacity', comp:'Compliance', reg:'Regulator confidence', cost:'Monthly cost (COP, millions)', takeaways:'Key takeaways' };
            var tiers = es ? { Beginner:'Principiante', Good:'Bueno', Excellent:'Excelente' } : {};
            var perf = tiers[summary.performance] || summary.performance || '';
            function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
            var ins = '';
            if (summary.insights && summary.insights.length) {
                ins = '<hr class="my-3"><p><strong>' + L.takeaways + '</strong></p><ul style="text-align:left;max-width:560px;margin:0 auto;">';
                for (var i = 0; i < summary.insights.length; i++) { ins += '<li>' + esc(summary.insights[i]) + '</li>'; }
                ins += '</ul>';
            }
            return '<div class="text-center p-2">' +
                '<p class="lead mb-1">' + L.title + '</p>' +
                '<div style="font-size:2.4rem;font-weight:800;color:#1a73e8;">' + (summary.overall || 0) + '<span style="font-size:1.2rem;color:#888;">/100</span></div>' +
                '<p class="mb-1">' + L.perf + ': <strong>' + esc(perf) + '</strong></p>' +
                '<p class="text-muted" style="font-size:0.9rem;">' + L.tps + ': ' + (summary.totalTps || 0) + ' \u00b7 ' + L.comp + ': ' + (summary.finalCompliance || 0) + '/100 \u00b7 ' + L.reg + ': ' + (summary.finalRegulator || 0) + '/100 \u00b7 ' + L.cost + ': ' + Math.round(summary.finalCost || 0) + '</p>' +
                ins + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1].results || {};
            var arch = last.architectureScore || 0;
            var comp = last.complianceScore || 0;
            var reg = last.regulatorConfidence || 0;
            var tps = last.tpsCapacity || 0;
            var cost = last.monthlyCost || 0;
            var overall = (arch + comp + reg) / 3;

            var performance = 'Beginner';
            if (overall > 78 && tps >= 1260) performance = 'Excellent';
            else if (overall > 58) performance = 'Good';

            var t = window.mySimulation.t.bind(window.mySimulation);
            var insights = [];
            if (tps >= 1260) insights.push(t('insight_tps_ok'));
            else insights.push(t('insight_tps_low'));
            if (comp >= 70) insights.push(t('insight_compliance_ok'));
            else insights.push(t('insight_compliance_low'));
            if (reg >= 70) insights.push(t('insight_regulator_ok'));
            else insights.push(t('insight_regulator_low'));
            insights.push(t('insight_final_cost').split('{cost}').join(String(Math.round(cost))));
            var tierLabel = t('tier_' + performance.toLowerCase());

            return {
                totalPeriods: history.length,
                message: tierLabel + ' \u2014 ' + Math.round(overall) + '/100',
                performanceLabel: tierLabel,
                totalTps: tps,
                finalArch: arch,
                finalCompliance: comp,
                finalRegulator: reg,
                finalCost: cost,
                overall: Math.round(overall),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
